document.addEventListener("DOMContentLoaded",function(){var e=document.querySelectorAll("div.highlight");e.forEach(function(e){var t=document.createElement("button");t.className="copy-code-btn",t.textContent="copy",t.addEventListener("click",function(){var n=e.querySelector("code");if(!n)return;navigator.clipboard.writeText(n.innerText).then(function(){t.textContent="copied!",t.classList.add("copied"),setTimeout(function(){t.textContent="copy",t.classList.remove("copied")},2e3)})}),e.appendChild(t)})})